import { createHmac, randomBytes } from "crypto";
import { cookies } from "next/headers";

const JWT_SECRET =
  process.env.JWT_SECRET || "nexus-academy-dev-secret-change-in-prod";

export interface SessionPayload {
  userId: string;
  email: string | null;
  name: string | null;
  isGuest: boolean;
}

function base64url(buf: Buffer): string {
  return buf.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function createSessionToken(payload: SessionPayload): string {
  const header = base64url(Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })));
  const body = base64url(
    Buffer.from(
      JSON.stringify({
        ...payload,
        iat: Math.floor(Date.now() / 1000),
        exp: Math.floor(Date.now() / 1000) + 30 * 24 * 60 * 60,
      })
    )
  );
  const sig = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${body}`)
    .digest();
  return `${header}.${body}.${base64url(sig)}`;
}

export function verifySessionToken(token: string): SessionPayload | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return null;
    const [header, body, sig] = parts;
    const expectedSig = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${body}`)
      .digest();
    const actualSig = Buffer.from(sig.replace(/-/g, "+").replace(/_/g, "/"), "base64");
    if (!createHmac("sha256", JWT_SECRET)
      .update(`${header}.${body}`)
      .digest()
      .equals(actualSig)) return null;
    const data = JSON.parse(Buffer.from(body, "base64").toString());
    if (data.exp && data.exp < Math.floor(Date.now() / 1000)) return null;
    return {
      userId: data.userId as string,
      email: (data.email as string) ?? null,
      name: (data.name as string) ?? null,
      isGuest: (data.isGuest as boolean) ?? false,
    };
  } catch {
    return null;
  }
}

export async function getSession(): Promise<SessionPayload | null> {
  const cookieStore = await cookies();
  const token = cookieStore.get("nexus-session")?.value;
  if (!token) return null;
  return verifySessionToken(token);
}

export function generateOtp(): string {
  const bytes = randomBytes(4);
  const num = bytes.readUInt32BE(0) % 1000000;
  return num.toString().padStart(6, "0");
}
